        let mut orig = unsafe { std::mem::zeroed::<libc::termios>() };

        unsafe {
            if tcgetattr(0, &mut orig) < 0 {
                return Err(io::Error::last_os_error());
            }
        }

        let (rows, cols) = get_terminal_size()?;

        Ok(Terminal {
            orig_termios: orig,
            rows,
            cols,
        })
    }

    pub fn enable_raw_mode(&self) -> io::Result<()> {
        let mut raw = self.orig_termios;

        unsafe {
            raw.c_lflag &= !(libc::ECHO | libc::ICANON | libc::ISIG | libc::IEXTEN);
            raw.c_iflag &= !(libc::IXON | libc::ICRNL | libc::BRKINT | libc::INPCK | libc::ISTRIP);
            raw.c_oflag &= !libc::OPOST;
            raw.c_cflag |= libc::CS8;
            raw.c_cc[libc::VMIN] = 1;
            raw.c_cc[libc::VTIME] = 0;

            if tcsetattr(0, libc::TCSAFLUSH, &raw) < 0 {
                return Err(io::Error::last_os_error());
            }
        }

        Ok(())
    }

    pub fn disable_raw_mode(&self) -> io::Result<()> {
        unsafe {
            tcsetattr(0, libc::TCSAFLUSH, &self.orig_termios);
        }
        Ok(())
    }

    pub fn update_size(&mut self) -> io::Result<()> {
        let (rows, cols) = get_terminal_size()?;
        self.rows = rows;
        self.cols = cols;
        Ok(())
    }
}

fn get_terminal_size() -> io::Result<(usize, usize)> {
    unsafe {
        let mut ws = libc::winsize {
            ws_row: 0,
            ws_col: 0,
            ws_xpixel: 0,
            ws_ypixel: 0,
        };

        if libc::ioctl(1, libc::TIOCGWINSZ, &mut ws) == -1 || ws.ws_col == 0 {
            // Fallback: move cursor to bottom-right and query position
            let mut stdout = io::stdout();
            stdout.write_all(b"\x1b[999C\x1b[999B\x1b[6n")?;
            stdout.flush()?;

            let mut response = String::new();
            let stdin = io::stdin();
            let mut buf = [0u8; 32];

            loop {
                match stdin.lock().read(&mut buf) {
                    Ok(n) => {
                        for &b in &buf[..n] {
                            response.push(b as char);
                        }
                        if response.contains('R') {
                            break;
                        }
                    }
                    Err(_) => break,
                }
            }

            // Parse ESC[rows;colsR
            if let Some(start) = response.find('[') {
                let rest = &response[start+1..];
                if let Some(semi) = rest.find(';') {
                    let row_str = &rest[..semi];
                    let col_str = rest[semi+1..].trim_end_matches('R');
                    let rows = row_str.parse().unwrap_or(24);
                    let cols = col_str.parse().unwrap_or(80);
                    return Ok((rows, cols));
                }
            }

            Ok((24, 80))
        } else {
            Ok((ws.ws_row as usize, ws.ws_col as usize))
        }
    }
}

impl Drop for Terminal {
    fn drop(&mut self) {
        let _ = self.disable_raw_mode();
    }
}
