                            (b'1', b'~') => return Ok(Key::Home),
                            (b'3', b'~') => return Ok(Key::Delete),
                            (b'4', b'~') => return Ok(Key::End),
                            (b'5', b'~') => return Ok(Key::PageUp),
                            (b'6', b'~') => return Ok(Key::PageDown),
                            (b'7', b'~') => return Ok(Key::Home),
                            (b'8', b'~') => return Ok(Key::End),
