                                let mut mod_seq = [0u8; 2];
                                let nm = read_with_timeout(&mut stdin, &mut mod_seq[..1])?;
                                if nm == 0 { return Ok(Key::Unknown); }
                                let nm2 = read_with_timeout(&mut stdin, &mut mod_seq[1..2])?;
                                if nm2 == 0 { return Ok(Key::Unknown); }
                                // mod_seq[0] = modifier: 5=ctrl, 3=alt
                                // mod_seq[1] = letter
