                    b'A' => return Ok(Key::Up),
                    b'B' => return Ok(Key::Down),
                    b'C' => return Ok(Key::Right),
                    b'D' => return Ok(Key::Left),
                    b'H' => return Ok(Key::Home),
                    b'F' => return Ok(Key::End),
                    _ => return Ok(Key::Unknown),
                }
            } else {
                // Alt + key
                let ch = seq[0];
                if ch == 0x7f {
                    // Alt-Backspace
                    return Ok(Key::AltCtrl('h'));
                }
                if ch < 0x80 {
                    let c = ch as char;
                    // Handle Alt combinations
                    return Ok(Key::Alt(c));
                }
                return Ok(Key::Unknown);
            }
        }
        // Ctrl characters (0x01-0x1a, excluding 0x09 tab, 0x0a newline, 0x0d CR, 0x1b ESC)
        0x01 => return Ok(Key::Ctrl('a')),
        0x02 => return Ok(Key::Ctrl('b')),
        0x03 => return Ok(Key::Ctrl('c')),
        0x04 => return Ok(Key::Ctrl('d')),
        0x05 => return Ok(Key::Ctrl('e')),
        0x06 => return Ok(Key::Ctrl('f')),
        0x07 => return Ok(Key::Ctrl('g')),
        0x08 => return Ok(Key::Ctrl('h')), // also Backspace in some terminals
        0x09 => return Ok(Key::Tab),
        0x0a => return Ok(Key::Ctrl('j')),
        0x0b => return Ok(Key::Ctrl('k')),
        0x0c => return Ok(Key::Ctrl('l')),
        0x0d => return Ok(Key::Enter),     // Ctrl-M = Enter
        0x0e => return Ok(Key::Ctrl('n')),
        0x0f => return Ok(Key::Ctrl('o')),
        0x10 => return Ok(Key::Ctrl('p')),
        0x11 => return Ok(Key::Ctrl('q')),
        0x12 => return Ok(Key::Ctrl('r')),
        0x13 => return Ok(Key::Ctrl('s')),
        0x14 => return Ok(Key::Ctrl('t')),
        0x15 => return Ok(Key::Ctrl('u')),
        0x16 => return Ok(Key::Ctrl('v')),
        0x17 => return Ok(Key::Ctrl('w')),
        0x18 => return Ok(Key::Ctrl('x')),
        0x19 => return Ok(Key::Ctrl('y')),
        0x1a => return Ok(Key::Ctrl('z')),
        0x1c => return Ok(Key::Ctrl(']')), // Ctrl-]
        0x1d => return Ok(Key::Ctrl('[')), // Ctrl-[ (actually 0x1d is FS, but Ctrl-[ = ESC)
        // Wait - Ctrl-[ = 0x1b = ESC already handled above!
        // Let me check: Ctrl-[ is 0x1b, but 0x1d is Ctrl-] 
        // Actually:
        // Ctrl-[ = 0x1b (ESC)
        // Ctrl-\ = 0x1c
        // Ctrl-] = 0x1d
        // Ctrl-^ = 0x1e
        // Ctrl-_ = 0x1f
        // These aren't handled above, need to be here:
        _ if c < 0x20 => {
            // Map remaining control chars
            let letter = (c + b'@') as char;
            return Ok(Key::Ctrl(letter.to_lowercase().next().unwrap_or('?')));
        }
        _ => {
            // Regular character (could be multi-byte UTF-8)
            if c < 0x80 {
                return Ok(Key::Char(c as char));
            }
            // UTF-8 multi-byte sequence
            let mut utf8_bytes = vec![c];
            let extra = if c >= 0xF0 { 3 } else if c >= 0xE0 { 2 } else { 1 };
            for _ in 0..extra {
                let mut b = [0u8; 1];
                if read_with_timeout(&mut stdin, &mut b)? > 0 {
                    utf8_bytes.push(b[0]);
                }
            }
            if let Ok(s) = std::str::from_utf8(&utf8_bytes) {
                if let Some(ch) = s.chars().next() {
                    return Ok(Key::Char(ch));
                }
            }
            return Ok(Key::Unknown);
        }
    }

    Ok(Key::Unknown)
}

fn read_with_timeout<R: Read>(reader: &mut R, buf: &mut [u8]) -> io::Result<usize> {
    // Set stdin to non-blocking mode temporarily
    use std::os::unix::io::AsRawFd;
    let fd = io::stdin().as_raw_fd();

    unsafe {
        let flags = libc::fcntl(fd, libc::F_GETFL, 0);
        libc::fcntl(fd, libc::F_SETFL, flags | libc::O_NONBLOCK);

        let result = reader.read(buf);

        libc::fcntl(fd, libc::F_SETFL, flags); // restore

        match result {
            Ok(n) => Ok(n),
            Err(e) if e.kind() == io::ErrorKind::WouldBlock => Ok(0),
            Err(e) => Err(e),
        }
    }
}
