#[derive(Debug, Clone, Copy, PartialEq)]
pub enum HlColor {
    Normal,    // default
    Comment,   // 90 dark gray
    Keyword,   // 94 bright blue
    Type,      // 33 yellow
    Control,   // 91 bright red
    Number,    // 95 bright magenta
    String,    // 32 green
    Identifier,// 93 bright yellow (after fn/let/etc)
    Special,   // 96 bright cyan (self, None, null, nil, this, etc)
    Tilde,     // 37 white (for ~ empty line markers)
}

impl HlColor {
    pub fn ansi_code(&self) -> &'static str {
        match self {
            HlColor::Normal => "\x1b[39m",
            HlColor::Comment => "\x1b[90m",
            HlColor::Keyword => "\x1b[94m",
            HlColor::Type => "\x1b[33m",
            HlColor::Control => "\x1b[91m",
            HlColor::Number => "\x1b[95m",
            HlColor::String => "\x1b[32m",
            HlColor::Identifier => "\x1b[93m",
            HlColor::Special => "\x1b[96m",
            HlColor::Tilde => "\x1b[37m",
        }
    }

    pub fn reset() -> &'static str {
        "\x1b[39m"
    }
}

#[derive(Debug, Clone, PartialEq)]
pub enum Language {
    Plain,
    C,
    Cpp,
    Rust,
    Python,
    JavaScript,
    Go,
}

impl Language {
    pub fn from_filename(filename: &str) -> Language {
        let ext = filename.rsplit('.').next().unwrap_or("");
        match ext {
            "c" | "h" => Language::C,
            "cpp" | "cc" | "cxx" | "hpp" | "hh" | "hxx" => Language::Cpp,
            "rs" => Language::Rust,
            "py" => Language::Python,
            "js" => Language::JavaScript,
            "go" => Language::Go,
            _ => Language::Plain,
        }
    }

    pub fn name(&self) -> &'static str {
        match self {
            Language::Plain => "plain",
            Language::C => "c",
            Language::Cpp => "c++",
            Language::Rust => "rust",
            Language::Python => "python",
            Language::JavaScript => "javascript",
            Language::Go => "go",
        }
    }
}

/// Compute syntax highlighting for an entire file (all rows)
/// Returns a Vec<Vec<HlColor>> parallel to rows
pub fn highlight_rows(rows: &[String], lang: &Language) -> Vec<Vec<HlColor>> {
    match lang {
        Language::Plain => rows.iter().map(|r| vec![HlColor::Normal; r.len()]).collect(),
        Language::C => highlight_c_like(rows, false),
        Language::Cpp => highlight_c_like(rows, true),
        Language::Rust => highlight_rust(rows),
        Language::Python => highlight_python(rows),
        Language::JavaScript => highlight_javascript(rows),
        Language::Go => highlight_go(rows),
    }
}

