fn highlight_python(rows: &[String]) -> Vec<Vec<HlColor>> {
    let mut result: Vec<Vec<HlColor>> = Vec::new();
    // Python has no block comments, but has triple-quoted strings
    let mut in_triple_single = false;
    let mut in_triple_double = false;

    // Keywords that trigger next-identifier highlighting
    let next_id_kws = ["def", "class", "global", "nonlocal"];

    for row in rows {
        let chars: Vec<char> = row.chars().collect();
        let n = chars.len();
        let mut hl = vec![HlColor::Normal; n];
        let mut i = 0;

        if in_triple_double || in_triple_single {
            let delim = if in_triple_double { '"' } else { '\'' };
            while i < n {
                hl[i] = HlColor::String;
                if i + 2 < n && chars[i] == delim && chars[i+1] == delim && chars[i+2] == delim {
                    hl[i+1] = HlColor::String;
                    hl[i+2] = HlColor::String;
                    i += 3;
                    in_triple_double = false;
                    in_triple_single = false;
                    break;
                }
                i += 1;
            }
            if in_triple_double || in_triple_single {
                result.push(hl);
                continue;
            }
        }

        while i < n {
            // Line comment
            if chars[i] == '#' {
                for j in i..n {
                    hl[j] = HlColor::Comment;
                }
                break;
            }

            // Triple-quoted string
            if i + 2 < n && chars[i] == '"' && chars[i+1] == '"' && chars[i+2] == '"' {
                hl[i] = HlColor::String;
                hl[i+1] = HlColor::String;
                hl[i+2] = HlColor::String;
                i += 3;
                let delim = '"';
                while i < n {
                    hl[i] = HlColor::String;
                    if i + 2 < n && chars[i] == delim && chars[i+1] == delim && chars[i+2] == delim {
                        hl[i+1] = HlColor::String;
                        hl[i+2] = HlColor::String;
                        i += 3;
                        break;
                    }
                    i += 1;
                }
                if i == n {
                    in_triple_double = true;
                }
                continue;
            }

            if i + 2 < n && chars[i] == '\'' && chars[i+1] == '\'' && chars[i+2] == '\'' {
                hl[i] = HlColor::String;
                hl[i+1] = HlColor::String;
                hl[i+2] = HlColor::String;
                i += 3;
                let delim = '\'';
                while i < n {
                    hl[i] = HlColor::String;
                    if i + 2 < n && chars[i] == delim && chars[i+1] == delim && chars[i+2] == delim {
                        hl[i+1] = HlColor::String;
                        hl[i+2] = HlColor::String;
                        i += 3;
                        break;
                    }
                    i += 1;
                }
                if i == n {
                    in_triple_single = true;
                }
                continue;
            }

            // Regular string
            if chars[i] == '"' || chars[i] == '\'' {
                let quote = chars[i];
                hl[i] = HlColor::String;
                i += 1;
                while i < n {
                    hl[i] = HlColor::String;
                    if chars[i] == '\\' && i + 1 < n {
                        hl[i+1] = HlColor::String;
                        i += 2;
                        continue;
                    }
                    if chars[i] == quote {
                        i += 1;
                        break;
                    }
                    i += 1;
                }
                continue;
            }

            // f-string (starts with f" or f')
            if (chars[i] == 'f' || chars[i] == 'F' || chars[i] == 'r' || chars[i] == 'b') 
                && i + 1 < n && (chars[i+1] == '"' || chars[i+1] == '\'') 
            {
                // Highlight the prefix as part of the string
                hl[i] = HlColor::String;
                let quote = chars[i+1];
                hl[i+1] = HlColor::String;
                i += 2;
                // Check for triple quote
                if i + 1 < n && chars[i] == quote && chars[i+1] == quote {
                    hl[i] = HlColor::String;
                    hl[i+1] = HlColor::String;
                    i += 2;
                    while i < n {
                        hl[i] = HlColor::String;
                        if i + 2 < n && chars[i] == quote && chars[i+1] == quote && chars[i+2] == quote {
                            hl[i+1] = HlColor::String;
                            hl[i+2] = HlColor::String;
                            i += 3;
                            break;
                        }
                        i += 1;
                    }
                } else {
                    while i < n {
                        hl[i] = HlColor::String;
                        if chars[i] == '\\' && i + 1 < n {
                            hl[i+1] = HlColor::String;
                            i += 2;
                            continue;
                        }
                        if chars[i] == quote {
                            i += 1;
                            break;
                        }
                        i += 1;
                    }
                }
                continue;
            }

            // Number
            if chars[i].is_ascii_digit() {
                let prev_ok = i == 0 || is_word_boundary(chars[i-1]);
                if prev_ok {
                    while i < n && (chars[i].is_alphanumeric() || chars[i] == '.' || chars[i] == '_') {
                        hl[i] = HlColor::Number;
                        i += 1;
                    }
                    continue;
                }
            }

            // Word
            if chars[i].is_alphabetic() || chars[i] == '_' {
                let start = i;
                let word_start_ok = start == 0 || is_word_boundary(chars[start-1]);

                let mut end = i;
                while end < n && (chars[end].is_alphanumeric() || chars[end] == '_') {
                    end += 1;
                }

                let word: String = chars[start..end].iter().collect();

                if word_start_ok {
                    let color = get_word_color_python(&word);
                    if color != HlColor::Normal {
                        for j in start..end {
                            hl[j] = color;
                        }

                        if next_id_kws.contains(&word.as_str()) {
                            let mut k = end;
                            while k < n && chars[k].is_whitespace() { k += 1; }
                            if k < n && (chars[k].is_alphabetic() || chars[k] == '_') {
                                while k < n && (chars[k].is_alphanumeric() || chars[k] == '_') {
                                    hl[k] = HlColor::Identifier;
                                    k += 1;
                                }
                            }
                        }

                        i = end;
                        continue;
                    }
                }

                i = end;
                continue;
            }

            i += 1;
        }

        result.push(hl);
    }

    result
}

