                hl[i] = HlColor::Comment;
                if i + 1 < n && chars[i] == '*' && chars[i+1] == '/' {
                    hl[i+1] = HlColor::Comment;
                    i += 2;
                    in_block_comment = false;
                    break;
                }
                i += 1;
            }
            if in_block_comment {
                result.push(hl);
                continue;
            }
        }

        while i < n {
            // Line comment
            if i + 1 < n && chars[i] == '/' && chars[i+1] == '/' {
                for j in i..n {
                    hl[j] = HlColor::Comment;
                }
                break;
            }

            // Block comment start
            if i + 1 < n && chars[i] == '/' && chars[i+1] == '*' {
                hl[i] = HlColor::Comment;
                hl[i+1] = HlColor::Comment;
                i += 2;
                in_block_comment = true;
                while i < n {
                    hl[i] = HlColor::Comment;
                    if i + 1 < n && chars[i] == '*' && chars[i+1] == '/' {
                        hl[i+1] = HlColor::Comment;
                        i += 2;
                        in_block_comment = false;
                        break;
                    }
                    i += 1;
                }
                continue;
            }

            // String
            if chars[i] == '"' {
                let start = i;
                hl[i] = HlColor::String;
                i += 1;
                while i < n {
                    hl[i] = HlColor::String;
                    if chars[i] == '\\' && i + 1 < n {
                        hl[i+1] = HlColor::String;
                        i += 2;
                        continue;
                    }
                    if chars[i] == '"' {
                        i += 1;
                        break;
                    }
                    i += 1;
                }
                continue;
            }

            // Char literal
            if chars[i] == '\'' {
                hl[i] = HlColor::String;
                i += 1;
                while i < n {
                    hl[i] = HlColor::String;
                    if chars[i] == '\\' && i + 1 < n {
                        hl[i+1] = HlColor::String;
                        i += 2;
                        continue;
                    }
                    if chars[i] == '\'' {
                        i += 1;
                        break;
                    }
                    i += 1;
                }
                continue;
            }

            // Number
            if chars[i].is_ascii_digit() {
                let prev_ok = i == 0 || is_word_boundary(chars[i-1]);
                if prev_ok {
                    while i < n && (chars[i].is_alphanumeric() || chars[i] == '.' || chars[i] == '_') {
                        hl[i] = HlColor::Number;
                        i += 1;
                    }
                    continue;
                }
            }

            // Hex literal
            if i + 1 < n && chars[i] == '0' && (chars[i+1] == 'x' || chars[i+1] == 'X') {
                let prev_ok = i == 0 || is_word_boundary(chars[i-1]);
                if prev_ok {
                    hl[i] = HlColor::Number;
                    hl[i+1] = HlColor::Number;
                    i += 2;
                    while i < n && chars[i].is_ascii_hexdigit() {
                        hl[i] = HlColor::Number;
                        i += 1;
                    }
                    continue;
                }
            }

            // Word
            if chars[i].is_alphabetic() || chars[i] == '_' {
                let start = i;
                let word_start_ok = start == 0 || is_word_boundary(chars[start-1]);

                let mut end = i;
                while end < n && (chars[end].is_alphanumeric() || chars[end] == '_') {
                    end += 1;
                }

                let word: String = chars[start..end].iter().collect();

                if word_start_ok {
                    // Check keywords
                    let color = get_word_color_c(&word, is_cpp);
                    if color != HlColor::Normal {
                        for j in start..end {
                            hl[j] = color;
                        }

                        // Check if next identifier should be highlighted
                        if is_cpp && next_id_keywords.contains(&word.as_str()) && color == HlColor::Keyword {
                            // Skip whitespace and highlight next word
                            let mut k = end;
                            while k < n && chars[k].is_whitespace() { k += 1; }
                            if k < n && (chars[k].is_alphabetic() || chars[k] == '_') {
                                let id_start = k;
                                while k < n && (chars[k].is_alphanumeric() || chars[k] == '_') {
                                    hl[k] = HlColor::Identifier;
                                    k += 1;
                                }
                            }
                        }

                        // After "class": highlight next identifier
                        if word == "class" {
                            let mut k = end;
                            while k < n && chars[k].is_whitespace() { k += 1; }
                            if k < n && (chars[k].is_alphabetic() || chars[k] == '_') {
                                let id_start = k;
                                while k < n && (chars[k].is_alphanumeric() || chars[k] == '_') {
                                    hl[k] = HlColor::Identifier;
                                    k += 1;
                                }
                            }
                        }

                        // After "namespace": highlight next identifier
                        if word == "namespace" {
                            let mut k = end;
                            while k < n && chars[k].is_whitespace() { k += 1; }
                            if k < n && (chars[k].is_alphabetic() || chars[k] == '_') {
                                let id_start = k;
                                while k < n && (chars[k].is_alphanumeric() || chars[k] == '_') {
                                    hl[k] = HlColor::Identifier;
                                    k += 1;
                                }
                            }
                        }

                        i = end;
                        continue;
                    }
                }

                i = end;
                continue;
            }

            i += 1;
        }

        result.push(hl);
    }

    result
}

fn get_word_color_c(word: &str, is_cpp: bool) -> HlColor {
    // Control flow
    if c_control().contains(&word) {
        return HlColor::Control;
    }

    // C++ specific additions
    if is_cpp {
        // bool is keyword in C++
        if word == "bool" {
            return HlColor::Keyword;
        }
        if word == "nullptr" {
            return HlColor::Keyword;
        }
        if word == "true" || word == "false" {
            return HlColor::Number;
        }
    } else {
        // C: true/false are macros but still highlighted as numbers
        if word == "true" || word == "false" {
            return HlColor::Number;
        }
    }

    // Shared keywords
    let all_kws: &[&str] = if is_cpp {
        &[
            "typedef", "struct", "using", "namespace", "class", "const",
            "auto", "public", "private", "protected", "virtual", "static",
            "inline", "extern", "template", "typename", "new", "delete",
            "sizeof", "enum", "union", "operator", "friend",
            "volatile", "register", "explicit", "mutable",
            "noexcept", "constexpr", "decltype", "override", "final",
            "this",
        ]
    } else {
        &[
            "typedef", "struct", "const", "auto", "static",
            "inline", "extern", "sizeof", "enum", "union",
            "volatile", "register",
        ]
    };

    if all_kws.contains(&word) {
        return HlColor::Keyword;
    }

    // Types
    let types = c_types();
    if types.contains(&word) {
        return HlColor::Type;
    }

    HlColor::Normal
}

fn highlight_rust(rows: &[String]) -> Vec<Vec<HlColor>> {
    let mut result: Vec<Vec<HlColor>> = Vec::new();
    let mut in_block_comment = false;

    // Keywords that trigger identifier highlighting
    let next_id_kws = ["fn", "let", "struct", "const", "mod", "trait", "enum"];
    // Note: "static", "type", "impl" do NOT trigger identifier highlighting

    for row in rows {
        let chars: Vec<char> = row.chars().collect();
        let n = chars.len();
        let mut hl = vec![HlColor::Normal; n];
        let mut i = 0;
        let mut char_positions: Vec<usize> = Vec::new();

        // Build char positions (byte offsets are tricky with UTF-8)
        // We work with char indices here

        if in_block_comment {
            while i < n {
                hl[i] = HlColor::Comment;
                if i + 1 < n && chars[i] == '*' && chars[i+1] == '/' {
                    hl[i+1] = HlColor::Comment;
                    i += 2;
                    in_block_comment = false;
                    break;
                }
                i += 1;
            }
            if in_block_comment {
                result.push(hl);
                continue;
            }
        }

        while i < n {
            // Line comment
            if i + 1 < n && chars[i] == '/' && chars[i+1] == '/' {
                for j in i..n {
                    hl[j] = HlColor::Comment;
                }
                break;
            }

            // Block comment
            if i + 1 < n && chars[i] == '/' && chars[i+1] == '*' {
                hl[i] = HlColor::Comment;
                hl[i+1] = HlColor::Comment;
                i += 2;
                in_block_comment = true;
                while i < n {
                    hl[i] = HlColor::Comment;
                    if i + 1 < n && chars[i] == '*' && chars[i+1] == '/' {
                        hl[i+1] = HlColor::Comment;
                        i += 2;
                        in_block_comment = false;
                        break;
                    }
                    i += 1;
                }
                continue;
            }

            // String
            if chars[i] == '"' {
                hl[i] = HlColor::String;
                i += 1;
                while i < n {
                    hl[i] = HlColor::String;
                    if chars[i] == '\\' && i + 1 < n {
                        hl[i+1] = HlColor::String;
                        i += 2;
                        continue;
                    }
                    if chars[i] == '"' {
                        i += 1;
                        break;
                    }
                    i += 1;
                }
                continue;
            }

            // Char literal (but not lifetime!)
            // Char: 'x', '\n', '\u{...}'
            // Lifetime: 'a, 'static
            if chars[i] == '\'' {
                // Check if it's a lifetime: next char is letter and not followed by '
                let is_lifetime = if i + 1 < n && (chars[i+1].is_alphabetic() || chars[i+1] == '_') {
                    // Check that it's not a char literal (single char followed by ')
                    let mut k = i + 1;
                    while k < n && (chars[k].is_alphanumeric() || chars[k] == '_') {
                        k += 1;
                    }
                    k >= n || chars[k] != '\'' 
                } else {
                    false
                };

                if !is_lifetime {
                    hl[i] = HlColor::String;
                    i += 1;
                    while i < n {
                        hl[i] = HlColor::String;
                        if chars[i] == '\\' && i + 1 < n {
                            hl[i+1] = HlColor::String;
                            i += 2;
                            continue;
                        }
                        if chars[i] == '\'' {
                            i += 1;
                            break;
                        }
                        i += 1;
                    }
                    continue;
                }
            }

            // Number (including floats like 3.14, integers)
            if chars[i].is_ascii_digit() {
                let prev_ok = i == 0 || is_word_boundary(chars[i-1]);
                if prev_ok {
                    while i < n && (chars[i].is_alphanumeric() || chars[i] == '.' || chars[i] == '_') {
                        hl[i] = HlColor::Number;
                        i += 1;
                    }
                    continue;
                }
            }

            // Word
            if chars[i].is_alphabetic() || chars[i] == '_' {
                let start = i;
                let word_start_ok = start == 0 || is_word_boundary(chars[start-1]);

                let mut end = i;
                while end < n && (chars[end].is_alphanumeric() || chars[end] == '_') {
                    end += 1;
                }

                let word: String = chars[start..end].iter().collect();

                if word_start_ok {
                    let color = get_word_color_rust(&word);
                    if color != HlColor::Normal {
                        for j in start..end {
                            hl[j] = color;
                        }

                        // After certain keywords, highlight next identifier
                        if (color == HlColor::Keyword || color == HlColor::Control) 
                            && next_id_kws.contains(&word.as_str()) 
                        {
                            // Skip 'mut' if present, then highlight next word
                            let mut k = end;
                            while k < n && chars[k].is_whitespace() { k += 1; }

                            // Skip 'mut' keyword
                            if k + 3 <= n {
                                let maybe_mut: String = chars[k..k.min(k+3)].iter().collect();
                                if maybe_mut == "mut" && (k+3 >= n || is_word_boundary(chars[k+3])) {
                                    // Color 'mut' as keyword
                                    for j in k..k+3 {
                                        hl[j] = HlColor::Keyword;
                                    }
                                    k += 3;
                                    while k < n && chars[k].is_whitespace() { k += 1; }
                                }
                            }

                            if k < n && (chars[k].is_alphabetic() || chars[k] == '_') {
                                let id_start = k;
                                while k < n && (chars[k].is_alphanumeric() || chars[k] == '_') {
                                    hl[k] = HlColor::Identifier;
                                    k += 1;
                                }
                            }
                        }

                        i = end;
                        continue;
                    }
                }

                i = end;
                continue;
            }

            i += 1;
        }

        result.push(hl);
    }

    result
}

fn get_word_color_rust(word: &str) -> HlColor {
    if rust_control().contains(&word) {
        return HlColor::Control;
    }

    if word == "true" || word == "false" {
        return HlColor::Number;
    }

    if rust_keywords().contains(&word) {
        return HlColor::Keyword;
    }

    if rust_types().contains(&word) {
        return HlColor::Type;
    }

    HlColor::Normal
}

fn highlight_python(rows: &[String]) -> Vec<Vec<HlColor>> {
    let mut result: Vec<Vec<HlColor>> = Vec::new();
    // Python has no block comments, but has triple-quoted strings
    let mut in_triple_single = false;
    let mut in_triple_double = false;

    // Keywords that trigger next-identifier highlighting
    let next_id_kws = ["def", "class", "global", "nonlocal"];

    for row in rows {
        let chars: Vec<char> = row.chars().collect();
        let n = chars.len();
        let mut hl = vec![HlColor::Normal; n];
        let mut i = 0;

        if in_triple_double || in_triple_single {
            let delim = if in_triple_double { '"' } else { '\'' };
            while i < n {
                hl[i] = HlColor::String;
                if i + 2 < n && chars[i] == delim && chars[i+1] == delim && chars[i+2] == delim {
                    hl[i+1] = HlColor::String;
                    hl[i+2] = HlColor::String;
                    i += 3;
                    in_triple_double = false;
                    in_triple_single = false;
                    break;
                }
                i += 1;
            }
            if in_triple_double || in_triple_single {
                result.push(hl);
                continue;
            }
        }

        while i < n {
            // Line comment
            if chars[i] == '#' {
                for j in i..n {
                    hl[j] = HlColor::Comment;
                }
                break;
            }

            // Triple-quoted string
            if i + 2 < n && chars[i] == '"' && chars[i+1] == '"' && chars[i+2] == '"' {
                hl[i] = HlColor::String;
                hl[i+1] = HlColor::String;
                hl[i+2] = HlColor::String;
                i += 3;
                let delim = '"';
                while i < n {
                    hl[i] = HlColor::String;
                    if i + 2 < n && chars[i] == delim && chars[i+1] == delim && chars[i+2] == delim {
                        hl[i+1] = HlColor::String;
                        hl[i+2] = HlColor::String;
                        i += 3;
                        break;
                    }
                    i += 1;
                }
                if i == n {
                    in_triple_double = true;
                }
                continue;
            }

            if i + 2 < n && chars[i] == '\'' && chars[i+1] == '\'' && chars[i+2] == '\'' {
                hl[i] = HlColor::String;
                hl[i+1] = HlColor::String;
                hl[i+2] = HlColor::String;
                i += 3;
                let delim = '\'';
                while i < n {
                    hl[i] = HlColor::String;
                    if i + 2 < n && chars[i] == delim && chars[i+1] == delim && chars[i+2] == delim {
                        hl[i+1] = HlColor::String;
                        hl[i+2] = HlColor::String;
                        i += 3;
                        break;
                    }
                    i += 1;
                }
                if i == n {
                    in_triple_single = true;
                }
                continue;
            }

            // Regular string
            if chars[i] == '"' || chars[i] == '\'' {
                let quote = chars[i];
                hl[i] = HlColor::String;
                i += 1;
                while i < n {
                    hl[i] = HlColor::String;
                    if chars[i] == '\\' && i + 1 < n {
                        hl[i+1] = HlColor::String;
                        i += 2;
                        continue;
                    }
                    if chars[i] == quote {
                        i += 1;
                        break;
                    }
                    i += 1;
                }
                continue;
            }

            // f-string (starts with f" or f')
            if (chars[i] == 'f' || chars[i] == 'F' || chars[i] == 'r' || chars[i] == 'b') 
                && i + 1 < n && (chars[i+1] == '"' || chars[i+1] == '\'') 
            {
                // Highlight the prefix as part of the string
                hl[i] = HlColor::String;
                let quote = chars[i+1];
                hl[i+1] = HlColor::String;
                i += 2;
                // Check for triple quote
                if i + 1 < n && chars[i] == quote && chars[i+1] == quote {
                    hl[i] = HlColor::String;
                    hl[i+1] = HlColor::String;
                    i += 2;
                    while i < n {
                        hl[i] = HlColor::String;
                        if i + 2 < n && chars[i] == quote && chars[i+1] == quote && chars[i+2] == quote {
                            hl[i+1] = HlColor::String;
                            hl[i+2] = HlColor::String;
                            i += 3;
                            break;
                        }
                        i += 1;
                    }
                } else {
                    while i < n {
                        hl[i] = HlColor::String;
                        if chars[i] == '\\' && i + 1 < n {
                            hl[i+1] = HlColor::String;
                            i += 2;
                            continue;
                        }
                        if chars[i] == quote {
                            i += 1;
                            break;
                        }
                        i += 1;
                    }
                }
                continue;
            }

            // Number
            if chars[i].is_ascii_digit() {
                let prev_ok = i == 0 || is_word_boundary(chars[i-1]);
                if prev_ok {
                    while i < n && (chars[i].is_alphanumeric() || chars[i] == '.' || chars[i] == '_') {
                        hl[i] = HlColor::Number;
                        i += 1;
                    }
                    continue;
                }
            }

            // Word
            if chars[i].is_alphabetic() || chars[i] == '_' {
                let start = i;
                let word_start_ok = start == 0 || is_word_boundary(chars[start-1]);

                let mut end = i;
                while end < n && (chars[end].is_alphanumeric() || chars[end] == '_') {
                    end += 1;
                }

                let word: String = chars[start..end].iter().collect();

                if word_start_ok {
                    let color = get_word_color_python(&word);
                    if color != HlColor::Normal {
                        for j in start..end {
                            hl[j] = color;
                        }

                        if next_id_kws.contains(&word.as_str()) {
                            let mut k = end;
                            while k < n && chars[k].is_whitespace() { k += 1; }
                            if k < n && (chars[k].is_alphabetic() || chars[k] == '_') {
                                while k < n && (chars[k].is_alphanumeric() || chars[k] == '_') {
                                    hl[k] = HlColor::Identifier;
                                    k += 1;
                                }
                            }
                        }

                        i = end;
                        continue;
                    }
                }

                i = end;
                continue;
            }

            i += 1;
        }

        result.push(hl);
    }

    result
}

fn get_word_color_python(word: &str) -> HlColor {
    if python_control().contains(&word) {
        return HlColor::Control;
    }

    if python_numbers().contains(&word) {
        return HlColor::Number;
    }

    if python_special().contains(&word) {
        return HlColor::Special;
    }

    if python_keywords().contains(&word) {
        return HlColor::Keyword;
    }

    if python_types().contains(&word) {
        return HlColor::Type;
    }

    HlColor::Normal
}

