                                while k < n && (chars[k].is_alphanumeric() || chars[k] == '_' || chars[k] == '$') {
                                    hl[k] = HlColor::Identifier;
                                    k += 1;
                                }
                            }
                        }

                        i = end;
                        continue;
                    }
                }

                i = end;
                continue;
            }

            i += 1;
        }

        result.push(hl);
    }

    result
}

fn get_word_color_js(word: &str) -> HlColor {
    if js_control().contains(&word) {
        return HlColor::Control;
    }

    if word == "true" || word == "false" {
        return HlColor::Number;
    }

    if js_special().contains(&word) {
        return HlColor::Special;
    }

    if js_keywords().contains(&word) {
        return HlColor::Keyword;
    }

    if js_types().contains(&word) {
        return HlColor::Type;
    }

    HlColor::Normal
}

fn highlight_go(rows: &[String]) -> Vec<Vec<HlColor>> {
    let mut result: Vec<Vec<HlColor>> = Vec::new();
    let mut in_block_comment = false;

    let next_id_kws = ["func", "package", "var", "const", "type"];

    for row in rows {
        let chars: Vec<char> = row.chars().collect();
        let n = chars.len();
        let mut hl = vec![HlColor::Normal; n];
        let mut i = 0;

        if in_block_comment {
            while i < n {
                hl[i] = HlColor::Comment;
                if i + 1 < n && chars[i] == '*' && chars[i+1] == '/' {
                    hl[i+1] = HlColor::Comment;
                    i += 2;
                    in_block_comment = false;
                    break;
                }
                i += 1;
            }
            if in_block_comment {
                result.push(hl);
                continue;
            }
        }

        while i < n {
            // Line comment
            if i + 1 < n && chars[i] == '/' && chars[i+1] == '/' {
                for j in i..n {
                    hl[j] = HlColor::Comment;
                }
                break;
            }

            // Block comment
            if i + 1 < n && chars[i] == '/' && chars[i+1] == '*' {
                hl[i] = HlColor::Comment;
                hl[i+1] = HlColor::Comment;
                i += 2;
                in_block_comment = true;
                while i < n {
                    hl[i] = HlColor::Comment;
                    if i + 1 < n && chars[i] == '*' && chars[i+1] == '/' {
                        hl[i+1] = HlColor::Comment;
                        i += 2;
                        in_block_comment = false;
                        break;
                    }
                    i += 1;
                }
                continue;
            }

            // Backtick string (raw string)
            if chars[i] == '`' {
                hl[i] = HlColor::String;
                i += 1;
                while i < n {
                    hl[i] = HlColor::String;
                    if chars[i] == '`' {
                        i += 1;
                        break;
                    }
                    i += 1;
                }
                continue;
            }

            // Regular string
            if chars[i] == '"' {
                hl[i] = HlColor::String;
                i += 1;
                while i < n {
                    hl[i] = HlColor::String;
                    if chars[i] == '\\' && i + 1 < n {
                        hl[i+1] = HlColor::String;
                        i += 2;
                        continue;
                    }
                    if chars[i] == '"' {
                        i += 1;
                        break;
                    }
                    i += 1;
                }
                continue;
            }

            // Char literal
            if chars[i] == '\'' {
                hl[i] = HlColor::String;
                i += 1;
                while i < n {
                    hl[i] = HlColor::String;
                    if chars[i] == '\\' && i + 1 < n {
                        hl[i+1] = HlColor::String;
                        i += 2;
                        continue;
                    }
                    if chars[i] == '\'' {
                        i += 1;
                        break;
                    }
                    i += 1;
                }
                continue;
            }

            // Number
            if chars[i].is_ascii_digit() {
                let prev_ok = i == 0 || is_word_boundary(chars[i-1]);
                if prev_ok {
                    while i < n && (chars[i].is_alphanumeric() || chars[i] == '.' || chars[i] == '_') {
                        hl[i] = HlColor::Number;
                        i += 1;
                    }
                    continue;
                }
            }

            // Word
            if chars[i].is_alphabetic() || chars[i] == '_' {
                let start = i;
                let word_start_ok = start == 0 || is_word_boundary(chars[start-1]);

                let mut end = i;
                while end < n && (chars[end].is_alphanumeric() || chars[end] == '_') {
                    end += 1;
                }

                let word: String = chars[start..end].iter().collect();

                if word_start_ok {
                    let color = get_word_color_go(&word);
                    if color != HlColor::Normal {
                        for j in start..end {
                            hl[j] = color;
                        }

                        if next_id_kws.contains(&word.as_str()) {
                            let mut k = end;
                            // Skip receiver for methods: func (r *Type) Name(...)
                            // If next is '(', skip to after ')'
                            while k < n && chars[k].is_whitespace() { k += 1; }
                            if k < n && chars[k] == '(' {
                                // Skip to after ')'
                                let mut depth = 1;
                                k += 1;
                                while k < n && depth > 0 {
                                    if chars[k] == '(' { depth += 1; }
                                    if chars[k] == ')' { depth -= 1; }
                                    k += 1;
                                }
                                while k < n && chars[k].is_whitespace() { k += 1; }
                            }

                            if k < n && (chars[k].is_alphabetic() || chars[k] == '_') {
                                while k < n && (chars[k].is_alphanumeric() || chars[k] == '_') {
                                    hl[k] = HlColor::Identifier;
                                    k += 1;
                                }
                            }
                        }

                        i = end;
                        continue;
                    }
                }

                i = end;
                continue;
            }

            i += 1;
        }

        result.push(hl);
    }

    result
}

fn get_word_color_go(word: &str) -> HlColor {
    if go_control().contains(&word) {
        return HlColor::Control;
    }

    if word == "true" || word == "false" {
        return HlColor::Number;
    }

    if go_special().contains(&word) {
        // nil -> Special
        if word == "nil" {
            return HlColor::Special;
        }
        // true/false already handled above
        return HlColor::Number;
    }

    if go_keywords().contains(&word) {
        return HlColor::Keyword;
    }

    if go_types().contains(&word) {
        return HlColor::Type;
    }

    HlColor::Normal
}
