            // At start of line - join with previous line
            let current = self.rows.remove(self.cy);
            self.cy -= 1;
            let prev_len = self.rows[self.cy].chars().count();
            self.rows[self.cy].push_str(&current);
            self.cx = prev_len;
        } else if self.cy < self.rows.len() {
            // Find previous word boundary
            let row_chars: Vec<char> = self.rows[self.cy].chars().collect();
            let mut end = self.cx;

            // Skip spaces
            while end > 0 && row_chars[end-1].is_whitespace() {
                end -= 1;
            }

            // Skip word chars
            while end > 0 && !row_chars[end-1].is_whitespace() {
                end -= 1;
            }

            // Delete from end to self.cx
            let row = &mut self.rows[self.cy];
            let start_byte = char_to_byte_pos(row, end);
            let end_byte = char_to_byte_pos(row, self.cx);
            row.replace_range(start_byte..end_byte, "");
            self.cx = end;
        }

