    /// Move cursor to next word
    fn move_word_forward(&mut self) {
        if self.cy >= self.rows.len() {
            return;
        }

        loop {
            let row_chars: Vec<char> = if self.cy < self.rows.len() {
                self.rows[self.cy].chars().collect()
            } else {
                break;
            };
            let row_len = row_chars.len();

            if self.cx >= row_len {
                // Move to next line
                if self.cy + 1 < self.rows.len() {
                    self.cy += 1;
                    self.cx = 0;
                } else if self.cy < self.rows.len() {
                    // At last line, end of content
                    self.cy = self.rows.len();
                    self.cx = 0;
                    break;
                }
                // Continue to find word start on new line
                let new_row_chars: Vec<char> = if self.cy < self.rows.len() {
                    self.rows[self.cy].chars().collect()
                } else {
                    break;
                };
                // Skip leading whitespace on new line
                let mut k = 0;
                while k < new_row_chars.len() && new_row_chars[k].is_whitespace() {
                    k += 1;
                }
                self.cx = k;
                break;
            }

            // Skip whitespace
            while self.cx < row_len && row_chars[self.cx].is_whitespace() {
                self.cx += 1;
            }

            if self.cx >= row_len {
                // Need to go to next line
                continue;
            }

            // Skip word chars
            while self.cx < row_len && !row_chars[self.cx].is_whitespace() {
                self.cx += 1;
            }

            // Now skip whitespace to get to next word
            while self.cx < row_len && row_chars[self.cx].is_whitespace() {
                self.cx += 1;
            }

            break;
        }
    }

    /// Move cursor to previous word
    fn move_word_backward(&mut self) {
        if self.cy == 0 && self.cx == 0 {
            return;
        }

        if self.cx == 0 {
            // Move to end of previous line
            self.cy -= 1;
            if self.cy < self.rows.len() {
                self.cx = self.rows[self.cy].chars().count();
            } else {
                self.cx = 0;
            }
            return;
        }

        if self.cy < self.rows.len() {
            let row_chars: Vec<char> = self.rows[self.cy].chars().collect();
            let mut pos = self.cx;

            // Skip whitespace going backward
            while pos > 0 && row_chars[pos-1].is_whitespace() {
                pos -= 1;
            }

            // Skip word going backward
            while pos > 0 && !row_chars[pos-1].is_whitespace() {
                pos -= 1;
            }

            self.cx = pos;
        }
    }

    /// Move to next paragraph (next non-empty line after an empty line)
    fn move_paragraph_forward(&mut self) {
        let nlines = self.rows.len();
        if self.cy >= nlines {
            return;
        }

        // Find next empty line
        let mut i = self.cy + 1;
        while i < nlines && !self.rows[i].trim().is_empty() {
            i += 1;
        }
        // Skip empty lines
        while i < nlines && self.rows[i].trim().is_empty() {
            i += 1;
        }

        if i < nlines {
            self.cy = i;
        } else {
            self.cy = nlines.saturating_sub(1);
        }
        self.cx = 0;
    }

    /// Move to previous paragraph
    fn move_paragraph_backward(&mut self) {
        if self.cy == 0 {
            return;
        }

        let mut i = self.cy as isize - 1;
        // Skip empty lines going backward
        while i >= 0 && self.rows[i as usize].trim().is_empty() {
            i -= 1;
        }
        // Skip non-empty lines going backward
        while i >= 0 && !self.rows[i as usize].trim().is_empty() {
            i -= 1;
        }
        // i is now at an empty line or -1
        // The start of the paragraph is at i+1
        let para_start = (i + 1) as usize;
        self.cy = para_start;
        self.cx = 0;
    }
}

fn char_to_byte_pos(s: &str, char_idx: usize) -> usize {
    s.char_indices()
        .nth(char_idx)
        .map(|(b, _)| b)
        .unwrap_or(s.len())
}

/// The search state
struct SearchState {
    query: String,
    current_match: Option<(usize, usize)>, // (row, col)
    all_matches: Vec<(usize, usize)>,       // (row, col)
    match_idx: usize,
    original_cx: usize,
    original_cy: usize,
    original_row_offset: usize,
    original_col_offset: usize,
}

impl SearchState {
    fn new(buf: &TextBuffer) -> SearchState {
        SearchState {
            query: String::new(),
            current_match: None,
            all_matches: Vec::new(),
            match_idx: 0,
            original_cx: buf.cx,
            original_cy: buf.cy,
            original_row_offset: buf.row_offset,
            original_col_offset: buf.col_offset,
        }
    }

    fn find_all_matches(&mut self, buf: &TextBuffer) {
        self.all_matches.clear();
        if self.query.is_empty() {
            return;
        }
        for (row_idx, row) in buf.rows.iter().enumerate() {
            let mut start = 0;
            while let Some(pos) = row[start..].find(&self.query) {
                let byte_pos = start + pos;
                let col = row[..byte_pos].chars().count();
                self.all_matches.push((row_idx, col));
                start = byte_pos + self.query.len();
                if start >= row.len() { break; }
            }
        }
    }

    fn set_current_match(&mut self, idx: usize) {
        if self.all_matches.is_empty() {
            self.current_match = None;
            return;
        }
        self.match_idx = idx % self.all_matches.len();
        self.current_match = Some(self.all_matches[self.match_idx]);
    }

    fn advance(&mut self, forward: bool) {
        if self.all_matches.is_empty() { return; }
        if forward {
            self.match_idx = (self.match_idx + 1) % self.all_matches.len();
        } else {
            if self.match_idx == 0 {
                self.match_idx = self.all_matches.len() - 1;
            } else {
                self.match_idx -= 1;
            }
        }
        self.current_match = Some(self.all_matches[self.match_idx]);
    }
}

enum EditorMode {
    Normal,
    Search(SearchState),
    SavePrompt { input: String },
    OpenPrompt { input: String },
}

pub struct Editor {
    buffers: Vec<TextBuffer>,
    current_buf: usize,
    terminal: Terminal,
    mode: EditorMode,
    message: String,
    quit_confirm: bool,
}

impl Editor {
    pub fn run(files: Vec<String>) -> io::Result<()> {
        let terminal = Terminal::new()?;
        terminal.enable_raw_mode()?;

        // Hide cursor initially, set up terminal
        let mut stdout = io::stdout();
        write!(stdout, "\x1b[?25l")?; // hide cursor
        write!(stdout, "\x1b[2J")?;   // clear screen
        stdout.flush()?;

        let mut buffers: Vec<TextBuffer> = Vec::new();

        if files.is_empty() {
            buffers.push(TextBuffer::new());
        } else {
            for f in &files {
                match TextBuffer::from_file(f) {
                    Ok(buf) => buffers.push(buf),
                    Err(e) => {
                        // Create empty buffer with the filename
                        let mut buf = TextBuffer::new();
                        buf.filename = Some(PathBuf::from(f));
                        buf.lang = Language::from_filename(f);
                        buffers.push(buf);
                    }
                }
            }
        }

        if buffers.is_empty() {
            buffers.push(TextBuffer::new());
        }

        let mut editor = Editor {
            buffers,
            current_buf: 0,
            terminal,
            mode: EditorMode::Normal,
            message: "Ctrl-? for help".to_string(),
            quit_confirm: false,
        };

        editor.refresh_screen()?;

        loop {
            let key = input::read_key()?;

            let should_quit = editor.process_key(key)?;
            if should_quit {
                break;
            }

            editor.refresh_screen()?;
        }

        // Clean up: show cursor, clear screen
        let mut stdout = io::stdout();
        write!(stdout, "\x1b[?25h")?; // show cursor
        write!(stdout, "\x1b[2J\x1b[H")?;
        stdout.flush()?;

        Ok(())
    }

    fn buf(&self) -> &TextBuffer {
        &self.buffers[self.current_buf]
    }

    fn buf_mut(&mut self) -> &mut TextBuffer {
        &mut self.buffers[self.current_buf]
    }

    fn is_any_dirty(&self) -> bool {
        self.buffers.iter().any(|b| b.dirty)
    }

    fn process_key(&mut self, key: Key) -> io::Result<bool> {
        // Handle based on mode
        match &self.mode {
            EditorMode::Search(_) => {
                return self.process_search_key(key);
            }
            EditorMode::SavePrompt { .. } => {
                return self.process_save_prompt_key(key);
            }
            EditorMode::OpenPrompt { .. } => {
                return self.process_open_prompt_key(key);
            }
            EditorMode::Normal => {}
        }

        // Normal mode
        match key {
            Key::Ctrl('q') => {
                if self.is_any_dirty() && !self.quit_confirm {
                    self.quit_confirm = true;
                    self.message = "At least one file has unsaved changes! Press ^Q again to quit or ^S to save".to_string();
                    return Ok(false);
                }
                return Ok(true); // quit
            }

            Key::Ctrl('s') => {
                self.quit_confirm = false;
                self.do_save()?;
            }

            Key::Ctrl('o') => {
                self.quit_confirm = false;
                self.mode = EditorMode::OpenPrompt { input: String::new() };
                self.message = "Open:  (Empty name for new text buffer, ^G or ESC to cancel)".to_string();
            }

            Key::Ctrl('x') => {
                self.quit_confirm = false;
                if self.buffers.len() > 1 {
                    self.current_buf = (self.current_buf + 1) % self.buffers.len();
                    self.message = String::new();
                }
            }

            Key::Alt('x') => {
                self.quit_confirm = false;
                if self.buffers.len() > 1 {
                    if self.current_buf == 0 {
                        self.current_buf = self.buffers.len() - 1;
                    } else {
                        self.current_buf -= 1;
                    }
                    self.message = String::new();
                }
            }

            Key::Ctrl('p') | Key::Up => {
                self.quit_confirm = false;
                self.move_cursor_up();
                self.buf_mut().last_edit_kind = EditKind::None;
            }

            Key::Ctrl('n') | Key::Down => {
                self.quit_confirm = false;
                self.move_cursor_down();
                self.buf_mut().last_edit_kind = EditKind::None;
            }

            Key::Ctrl('f') | Key::Right => {
                self.quit_confirm = false;
                self.move_cursor_right();
                self.buf_mut().last_edit_kind = EditKind::None;
            }

            Key::Ctrl('b') | Key::Left => {
                self.quit_confirm = false;
                self.move_cursor_left();
                self.buf_mut().last_edit_kind = EditKind::None;
            }

            Key::Ctrl('a') | Key::AltLeft | Key::Home => {
                self.quit_confirm = false;
                self.buf_mut().cx = 0;
                self.buf_mut().last_edit_kind = EditKind::None;
            }

            Key::Ctrl('e') | Key::AltRight | Key::End => {
                self.quit_confirm = false;
                let cy = self.buf().cy;
                let len = if cy < self.buf().rows.len() {
                    self.buf().rows[cy].chars().count()
                } else {
                    0
                };
                self.buf_mut().cx = len;
                self.buf_mut().last_edit_kind = EditKind::None;
            }

            Key::Ctrl('[') | Key::Ctrl('v') | Key::PageDown => {
                self.quit_confirm = false;
                let page_size = self.screen_rows().saturating_sub(1);
                for _ in 0..page_size {
                    self.move_cursor_down();
                }
                self.buf_mut().last_edit_kind = EditKind::None;
            }

            Key::Ctrl(']') | Key::Alt('v') | Key::PageUp => {
                self.quit_confirm = false;
                let page_size = self.screen_rows().saturating_sub(1);
                for _ in 0..page_size {
                    self.move_cursor_up();
                }
                self.buf_mut().last_edit_kind = EditKind::None;
            }

            Key::Alt('f') | Key::CtrlRight => {
                self.quit_confirm = false;
                self.buf_mut().last_edit_kind = EditKind::None;
                self.buf_mut().move_word_forward();
            }

            Key::Alt('b') | Key::CtrlLeft => {
                self.quit_confirm = false;
                self.buf_mut().last_edit_kind = EditKind::None;
                self.buf_mut().move_word_backward();
            }

            Key::Alt('n') | Key::CtrlDown => {
                self.quit_confirm = false;
                self.buf_mut().last_edit_kind = EditKind::None;
                self.buf_mut().move_paragraph_forward();
            }

            Key::Alt('p') | Key::CtrlUp => {
                self.quit_confirm = false;
                self.buf_mut().last_edit_kind = EditKind::None;
                self.buf_mut().move_paragraph_backward();
            }

            Key::Alt('<') => {
                self.quit_confirm = false;
                self.buf_mut().cy = 0;
                self.buf_mut().cx = 0;
                self.buf_mut().last_edit_kind = EditKind::None;
            }

            Key::Alt('>') => {
                self.quit_confirm = false;
                let nlines = self.buf().rows.len();
                self.buf_mut().cy = nlines;
                self.buf_mut().cx = 0;
                self.buf_mut().last_edit_kind = EditKind::None;
            }

            Key::Ctrl('h') | Key::Backspace => {
                self.quit_confirm = false;
                self.buf_mut().delete_char();
            }

            Key::Ctrl('d') | Key::Delete => {
                self.quit_confirm = false;
                self.buf_mut().delete_next_char();
            }

            Key::Ctrl('w') => {
                self.quit_confirm = false;
                self.buf_mut().delete_word();
            }

            Key::Ctrl('j') => {
                self.quit_confirm = false;
                self.buf_mut().delete_to_start_of_line();
            }

            Key::Ctrl('k') => {
                self.quit_confirm = false;
                self.buf_mut().delete_to_end_of_line();
            }

            Key::Ctrl('u') => {
                self.quit_confirm = false;
                self.buf_mut().undo();
                // Update dirty flag
                self.update_dirty_after_undo();
            }

            Key::Ctrl('r') => {
                self.quit_confirm = false;
                self.buf_mut().redo();
            }

            Key::Ctrl('g') => {
                self.quit_confirm = false;
                let ss = SearchState::new(self.buf());
                self.mode = EditorMode::Search(ss);
                self.message = "Search:  (^F or ^N or RIGHT to forward, ^B or ^P or LEFT to back, ^G or ESC to cancel)".to_string();
            }

            Key::Enter | Key::Ctrl('m') => {
                self.quit_confirm = false;
                self.buf_mut().insert_newline();
            }

            Key::Ctrl('l') => {
                self.quit_confirm = false;
                // Refresh screen (will happen automatically)
            }

            Key::Ctrl('?') => {
                self.quit_confirm = false;
                // Show help
                self.show_help();
            }

            Key::Char(c) => {
                self.quit_confirm = false;
                self.buf_mut().insert_char(c, EditKind::Insert);
            }

            Key::Tab => {
                self.quit_confirm = false;
                self.buf_mut().insert_char('\t', EditKind::Insert);
            }

            _ => {
                // Unknown key - ignore
                self.quit_confirm = false;
            }
        }

        // After any key that wasn't quit, scroll to cursor
        self.scroll_to_cursor();

        Ok(false)
    }

    fn process_search_key(&mut self, key: Key) -> io::Result<bool> {
        let ss = match &mut self.mode {
            EditorMode::Search(ss) => ss,
            _ => return Ok(false),
        };

        match key {
            Key::Escape | Key::Ctrl('g') => {
                // Cancel search - restore position
                let (cx, cy, ro, co) = {
                    let ss = match &self.mode {
                        EditorMode::Search(ss) => ss,
                        _ => unreachable!(),
                    };
                    (ss.original_cx, ss.original_cy, ss.original_row_offset, ss.original_col_offset)
                };
                self.buf_mut().cx = cx;
                self.buf_mut().cy = cy;
                self.buf_mut().row_offset = ro;
                self.buf_mut().col_offset = co;

                let query = match &self.mode {
                    EditorMode::Search(ss) => ss.query.clone(),
                    _ => String::new(),
                };
                self.mode = EditorMode::Normal;
                if !query.is_empty() {
                    self.message = format!("Search: {} (^F or ^N or RIGHT to forward, ^B or ^P or LEFT to back, ^G or ESC to cancel)", query);
                } else {
                    self.message = "Canceled".to_string();
                }
            }

            Key::Enter => {
                // Confirm search, stay at current match position
                let query = match &self.mode {
                    EditorMode::Search(ss) => ss.query.clone(),
                    _ => String::new(),
                };
                self.mode = EditorMode::Normal;
                if !query.is_empty() {
                    self.message = format!("Search: {} (^F or ^N or RIGHT to forward, ^B or ^P or LEFT to back, ^G or ESC to cancel)", query);
                }
            }

            Key::Ctrl('f') | Key::Right | Key::Ctrl('n') | Key::Down => {
                // Forward search
                {
                    let ss = match &mut self.mode {
                        EditorMode::Search(ss) => ss,
                        _ => unreachable!(),
                    };
                    ss.advance(true);
                }
                self.apply_search_match();
            }

            Key::Ctrl('b') | Key::Left | Key::Ctrl('p') | Key::Up => {
                // Backward search
                {
                    let ss = match &mut self.mode {
                        EditorMode::Search(ss) => ss,
                        _ => unreachable!(),
                    };
                    ss.advance(false);
                }
                self.apply_search_match();
            }

            Key::Backspace | Key::Ctrl('h') => {
                let changed = {
                    let ss = match &mut self.mode {
                        EditorMode::Search(ss) => ss,
                        _ => unreachable!(),
                    };
                    if ss.query.pop().is_some() { true } else { false }
                };
                if changed {
                    self.update_search();
                }
                let (query, has_matches) = match &self.mode {
                    EditorMode::Search(ss) => (ss.query.clone(), !ss.all_matches.is_empty()),
                    _ => (String::new(), false),
                };
                self.message = format!("Search: {} (^F or ^N or RIGHT to forward, ^B or ^P or LEFT to back, ^G or ESC to cancel)", query);
            }

            Key::Char(c) => {
                {
                    let ss = match &mut self.mode {
                        EditorMode::Search(ss) => ss,
                        _ => unreachable!(),
                    };
                    ss.query.push(c);
                }
                self.update_search();
                let query = match &self.mode {
                    EditorMode::Search(ss) => ss.query.clone(),
                    _ => String::new(),
                };
                self.message = format!("Search: {} (^F or ^N or RIGHT to forward, ^B or ^P or LEFT to back, ^G or ESC to cancel)", query);
            }

            _ => {}
        }

        self.scroll_to_cursor();
        Ok(false)
    }

    fn update_search(&mut self) {
        // Re-find all matches and jump to first one from current position
        {
            let buf = &self.buffers[self.current_buf];
            let ss = match &mut self.mode {
                EditorMode::Search(ss) => ss,
                _ => return,
            };
            ss.find_all_matches(buf);
        }

        // Find match closest to original cursor position
        let (orig_cy, orig_cx) = {
            let ss = match &self.mode {
                EditorMode::Search(ss) => ss,
                _ => return,
            };
            (ss.original_cy, ss.original_cx)
        };

        let best_idx = {
            let ss = match &self.mode {
                EditorMode::Search(ss) => ss,
                _ => return,
            };
            if ss.all_matches.is_empty() {
                None
            } else {
                // Find first match at or after original cursor
                let mut best = 0;
                for (idx, &(row, col)) in ss.all_matches.iter().enumerate() {
                    if row > orig_cy || (row == orig_cy && col >= orig_cx) {
                        best = idx;
                        break;
                    }
                    best = idx;
                }
                Some(best)
            }
        };

        if let Some(idx) = best_idx {
            let ss = match &mut self.mode {
                EditorMode::Search(ss) => ss,
                _ => return,
            };
            ss.set_current_match(idx);
        }

        self.apply_search_match();
    }

    fn apply_search_match(&mut self) {
        let cm = match &self.mode {
            EditorMode::Search(ss) => ss.current_match,
            _ => return,
        };
        if let Some((row, col)) = cm {
            self.buf_mut().cy = row;
            self.buf_mut().cx = col;
        }
    }

    fn process_save_prompt_key(&mut self, key: Key) -> io::Result<bool> {
        match key {
            Key::Escape | Key::Ctrl('g') => {
                self.mode = EditorMode::Normal;
                self.message = "Canceled".to_string();
            }
            Key::Enter => {
                let filename = match &self.mode {
                    EditorMode::SavePrompt { input } => input.clone(),
                    _ => String::new(),
                };
                self.mode = EditorMode::Normal;
                if !filename.is_empty() {
                    self.buf_mut().filename = Some(PathBuf::from(&filename));
                    self.buf_mut().lang = Language::from_filename(&filename);
                    self.buf_mut().update_hl();
                    self.do_save()?;
                } else {
                    self.message = "Canceled".to_string();
                }
            }
            Key::Backspace | Key::Ctrl('h') => {
                if let EditorMode::SavePrompt { input } = &mut self.mode {
                    input.pop();
                }
                let q = match &self.mode {
                    EditorMode::SavePrompt { input } => input.clone(),
                    _ => String::new(),
                };
                self.message = format!("Save as: {} (^G or ESC to cancel)", q);
            }
            Key::Char(c) => {
                if let EditorMode::SavePrompt { input } = &mut self.mode {
                    input.push(c);
                }
                let q = match &self.mode {
                    EditorMode::SavePrompt { input } => input.clone(),
                    _ => String::new(),
                };
                self.message = format!("Save as: {} (^G or ESC to cancel)", q);
            }
            _ => {}
        }
        self.scroll_to_cursor();
        Ok(false)
    }

    fn process_open_prompt_key(&mut self, key: Key) -> io::Result<bool> {
        match key {
            Key::Escape | Key::Ctrl('g') => {
                self.mode = EditorMode::Normal;
                self.message = "Canceled".to_string();
            }
            Key::Enter => {
                let filename = match &self.mode {
                    EditorMode::OpenPrompt { input } => input.clone(),
                    _ => String::new(),
                };
                self.mode = EditorMode::Normal;
                if filename.is_empty() {
                    // Create new empty buffer
                    self.buffers.push(TextBuffer::new());
                    self.current_buf = self.buffers.len() - 1;
                    self.message = String::new();
                } else {
                    // Open file
                    match TextBuffer::from_file(&filename) {
                        Ok(buf) => {
                            self.buffers.push(buf);
                            self.current_buf = self.buffers.len() - 1;
                            self.message = String::new();
                        }
                        Err(e) => {
                            // Create new buffer with that filename
                            let mut buf = TextBuffer::new();
                            buf.filename = Some(PathBuf::from(&filename));
                            buf.lang = Language::from_filename(&filename);
                            self.buffers.push(buf);
                            self.current_buf = self.buffers.len() - 1;
                            self.message = format!("{}: {}", filename, e);
                        }
                    }
                }
            }
            Key::Backspace | Key::Ctrl('h') => {
                if let EditorMode::OpenPrompt { input } = &mut self.mode {
                    input.pop();
                }
                let q = match &self.mode {
                    EditorMode::OpenPrompt { input } => input.clone(),
                    _ => String::new(),
                };
                self.message = format!("Open: {} (Empty name for new text buffer, ^G or ESC to cancel)", q);
            }
            Key::Char(c) => {
                if let EditorMode::OpenPrompt { input } = &mut self.mode {
                    input.push(c);
                }
                let q = match &self.mode {
                    EditorMode::OpenPrompt { input } => input.clone(),
                    _ => String::new(),
                };
                self.message = format!("Open: {} (Empty name for new text buffer, ^G or ESC to cancel)", q);
            }
            _ => {}
        }
        self.scroll_to_cursor();
        Ok(false)
    }

    fn do_save(&mut self) -> io::Result<()> {
        if self.buf().filename.is_none() {
            // Ask for filename
            self.mode = EditorMode::SavePrompt { input: String::new() };
            self.message = "Save as:  (^G or ESC to cancel)".to_string();
            return Ok(());
        }

        match self.buf_mut().save() {
            Ok(n) => {
                let path = self.buf().filename.as_ref().unwrap().display().to_string();
                self.message = format!("{} bytes written to {}", n, path);
            }
            Err(e) => {
                self.message = format!("Error saving: {}", e);
            }
        }

        Ok(())
    }

    fn update_dirty_after_undo(&mut self) {
        // After undo, check if we're back to "clean" state
        // Simple heuristic: if undo_stack is empty, we're back to original
        // But this isn't quite right because we might have saved in the middle
        // For now, just mark dirty if there are any pending changes
        // We'll rely on save to clear dirty flag
        let buf = self.buf_mut();
        if buf.undo_stack.is_empty() {
            // Potentially back to original state
            // We can't be sure without a saved snapshot, so just leave dirty as-is
            // unless we explicitly track it
        }
    }

    fn show_help(&mut self) {
        self.message = "Ctrl-? for help".to_string();
    }

    fn screen_rows(&self) -> usize {
        self.terminal.rows.saturating_sub(2) // 2 rows for status bar + message
    }

    fn screen_cols(&self) -> usize {
        self.terminal.cols
    }

    fn move_cursor_up(&mut self) {
        let buf = self.buf_mut();
        if buf.cy > 0 {
            buf.cy -= 1;
            // Clamp cx to line length
            let row_len = buf.rows[buf.cy].chars().count();
            if buf.cx > row_len {
                buf.cx = row_len;
            }
        }
    }

    fn move_cursor_down(&mut self) {
        let buf = self.buf_mut();
        // Can move to rows.len() (one past last)
        if buf.cy < buf.rows.len() {
            buf.cy += 1;
            // Clamp cx
            let row_len = if buf.cy < buf.rows.len() {
                buf.rows[buf.cy].chars().count()
            } else {
                0
            };
            if buf.cx > row_len {
                buf.cx = row_len;
            }
        }
    }

    fn move_cursor_right(&mut self) {
        let buf = self.buf_mut();
        if buf.cy < buf.rows.len() {
            let row_len = buf.rows[buf.cy].chars().count();
            if buf.cx < row_len {
                buf.cx += 1;
            } else {
                // Move to start of next line
                buf.cy += 1;
                buf.cx = 0;
            }
        }
    }

    fn move_cursor_left(&mut self) {
        let buf = self.buf_mut();
        if buf.cx > 0 {
            buf.cx -= 1;
        } else if buf.cy > 0 {
            // Move to end of previous line
            buf.cy -= 1;
            buf.cx = buf.rows[buf.cy].chars().count();
        }
    }

    fn scroll_to_cursor(&mut self) {
        let buf = &mut self.buffers[self.current_buf];
        let screen_rows = self.terminal.rows.saturating_sub(2);
        let screen_cols = self.terminal.cols;

        // Vertical scroll
        if buf.cy < buf.row_offset {
            buf.row_offset = buf.cy;
        }
        if buf.cy >= buf.row_offset + screen_rows {
            buf.row_offset = buf.cy - screen_rows + 1;
        }

        // Horizontal scroll
        let rx = self.get_render_x(buf.cy, buf.cx);
        if rx < buf.col_offset {
            buf.col_offset = rx;
        }
        if rx >= buf.col_offset + screen_cols {
            buf.col_offset = rx - screen_cols + 1;
        }
    }

    fn get_render_x(&self, row: usize, cx: usize) -> usize {
        let buf = self.buf();
        if row >= buf.rows.len() {
            return cx;
        }
        let row_str = &buf.rows[row];
        let mut rx = 0;
        for (i, c) in row_str.chars().enumerate() {
            if i >= cx { break; }
            if c == '\t' {
                rx = (rx / TAB_SIZE + 1) * TAB_SIZE;
            } else {
                rx += 1;
            }
        }
        rx
    }

    fn refresh_screen(&mut self) -> io::Result<()> {
        self.scroll_to_cursor();

        let mut output = String::new();

        // Hide cursor
        output.push_str("\x1b[?25l");
        // Move cursor to top-left
        output.push_str("\x1b[H");

        self.draw_rows(&mut output);
        self.draw_status_bar(&mut output);
        self.draw_message_bar(&mut output);

        // Position cursor
        let buf = self.buf();
        let rx = self.get_render_x(buf.cy, buf.cx);
        let screen_row = buf.cy.saturating_sub(buf.row_offset) + 1;
        let screen_col = rx.saturating_sub(buf.col_offset) + 1;
        output.push_str(&format!("\x1b[{};{}H", screen_row, screen_col));

        // Show cursor
        output.push_str("\x1b[?25h");

        let mut stdout = io::stdout();
        stdout.write_all(output.as_bytes())?;
        stdout.flush()?;

        Ok(())
    }

    fn draw_rows(&self, output: &mut String) {
        let buf = self.buf();
        let screen_rows = self.terminal.rows.saturating_sub(2);
        let screen_cols = self.terminal.cols;
        let is_empty = buf.rows.len() == 1 && buf.rows[0].is_empty();

        // Search highlight info
        let (search_query, search_current, search_matches) = match &self.mode {
            EditorMode::Search(ss) => {
                (Some(ss.query.clone()), ss.current_match, ss.all_matches.clone())
            }
            _ => (None, None, Vec::new()),
        };

        for screen_row in 0..screen_rows {
            let file_row = screen_row + buf.row_offset;

            if file_row >= buf.rows.len() {
                // Check for welcome message
                if is_empty && screen_row == screen_rows / 3 {
                    let welcome = format!("Kiro editor -- version {}", VERSION);
                    let padding = (screen_cols.saturating_sub(welcome.len())) / 2;
                    output.push_str("\x1b[37m~\x1b[39m");
                    for _ in 1..padding {
                        output.push(' ');
                    }
                    if padding > 0 {
                        output.push_str(&welcome);
                    }
                } else {
                    output.push_str("\x1b[37m~\x1b[39m");
                }
            } else {
                let row = &buf.rows[file_row];
                let row_chars: Vec<char> = row.chars().collect();
                let row_hl = if file_row < buf.hl.len() {
                    &buf.hl[file_row]
                } else {
                    &[]
                };

                // Render the row with syntax highlighting
                let mut current_hl = HlColor::Normal;
                let mut col_count = 0;
                let mut char_idx = 0;

                // Skip col_offset characters  
                let mut rx = 0; // render position

                while char_idx < row_chars.len() && rx < buf.col_offset {
                    let c = row_chars[char_idx];
                    if c == '\t' {
                        let next_tab = (rx / TAB_SIZE + 1) * TAB_SIZE;
                        rx = next_tab;
                    } else {
                        rx += 1;
                    }
                    char_idx += 1;
                }

                // Now render from rx to rx + screen_cols
                let col_start = buf.col_offset;

                // Compute search highlights for this row
                let query_len = search_query.as_ref().map(|q| q.chars().count()).unwrap_or(0);

                while char_idx < row_chars.len() && col_count < screen_cols {
                    let c = row_chars[char_idx];
                    let hl = if char_idx < row_hl.len() {
                        row_hl[char_idx]
                    } else {
                        HlColor::Normal
                    };

                    // Check for search match highlighting
                    let in_search_current = if let Some(query) = &search_query {
                        if !query.is_empty() && query_len > 0 {
                            search_current.map(|(sr, sc)| {
                                sr == file_row && char_idx >= sc && char_idx < sc + query_len
                            }).unwrap_or(false)
                        } else { false }
                    } else { false };

                    let in_search_other = if let Some(query) = &search_query {
                        if !query.is_empty() && query_len > 0 {
                            !in_search_current && search_matches.iter().any(|&(sr, sc)| {
                                sr == file_row && char_idx >= sc && char_idx < sc + query_len
                            })
                        } else { false }
                    } else { false };

                    let display_hl = if in_search_current {
                        // Current match: bright white background, black text
                        if current_hl != HlColor::Normal {
                            output.push_str(HlColor::reset());
                        }
                        output.push_str("\x1b[30m\x1b[107m");
                        current_hl = HlColor::Normal; // will need reset
                    } else if in_search_other {
                        // Other match: yellow background, black text
                        if current_hl != HlColor::Normal {
                            output.push_str(HlColor::reset());
                        }
                        output.push_str("\x1b[30m\x1b[103m");
                        current_hl = HlColor::Normal;
                    } else {
                        if hl != current_hl {
                            output.push_str(HlColor::reset());
                            if hl != HlColor::Normal {
                                output.push_str(hl.ansi_code());
                            }
                            current_hl = hl;
                        }
                    };

                    if c == '\t' {
                        // Render tab as spaces
                        let next_tab = (rx / TAB_SIZE + 1) * TAB_SIZE;
                        let tab_width = next_tab - rx;
                        for _ in 0..tab_width {
                            if col_count < screen_cols {
                                output.push(' ');
                                col_count += 1;
                            }
                        }
                        rx = next_tab;
                    } else {
                        output.push(c);
                        col_count += 1;
                        rx += 1;
                    }

                    // Reset after search highlight
                    if in_search_current || in_search_other {
                        output.push_str("\x1b[39m\x1b[49m");
                        current_hl = HlColor::Normal;
                    }

                    char_idx += 1;
                }

                // Reset color at end of line
                if current_hl != HlColor::Normal {
                    output.push_str(HlColor::reset());
                }
            }

            output.push_str("\x1b[K"); // Clear to end of line
            output.push_str("\r\n");
        }
    }

    fn draw_status_bar(&self, output: &mut String) {
        output.push_str("\x1b[7m"); // Reverse video

        let buf = self.buf();
        let buf_num = self.current_buf + 1;
        let total_bufs = self.buffers.len();
        let is_dirty = buf.dirty;

        let left = if is_dirty {
            format!("{} - {}/{} (modified)", buf.display_name(), buf_num, total_bufs)
        } else {
            format!("{} - {}/{}", buf.display_name(), buf_num, total_bufs)
        };

        let right = format!("{} {}/{}", buf.lang.name(), buf.cy + 1, buf.rows.len());

        let screen_cols = self.terminal.cols;
        let total_len = left.len() + right.len();

        if total_len >= screen_cols {
            // Truncate left
            let truncated = &left[..screen_cols.saturating_sub(right.len())];
            output.push_str(truncated);
            output.push_str(&right);
        } else {
            output.push_str(&left);
            let spaces = screen_cols - total_len;
            for _ in 0..spaces {
                output.push(' ');
            }
            output.push_str(&right);
        }

        output.push_str("\x1b[0m\x1b[39m\x1b[49m"); // Reset
        output.push_str("\r\n");
    }

    fn draw_message_bar(&self, output: &mut String) {
        let msg = &self.message;
        let screen_cols = self.terminal.cols;

        // Show prompt input in message if in prompt mode
        let display = match &self.mode {
            EditorMode::SavePrompt { input } => {
                format!("Save as: {} (^G or ESC to cancel)", input)
            }
            EditorMode::OpenPrompt { input } => {
                format!("Open: {} (Empty name for new text buffer, ^G or ESC to cancel)", input)
            }
            EditorMode::Search(ss) => {
                format!("Search: {} (^F or ^N or RIGHT to forward, ^B or ^P or LEFT to back, ^G or ESC to cancel)", ss.query)
            }
            EditorMode::Normal => msg.clone(),
        };

        output.push_str("\x1b[K");
        if display.len() > screen_cols {
            output.push_str(&display[..screen_cols]);
        } else {
            output.push_str(&display);
        }
    }
}
