const IGNPAR: u32 = 0o0000004;
const PARMRK: u32 = 0o0000010;
const INPCK: u32 = 0o0000020;
const ISTRIP: u32 = 0o0000040;
const INLCR: u32 = 0o0000100;
const IGNCR: u32 = 0o0000200;
const ICRNL: u32 = 0o0000400;
const IUCLC: u32 = 0o0001000;
const IXON: u32 = 0o0002000;
const IXANY: u32 = 0o0004000;
const IXOFF: u32 = 0o0010000;
const OPOST: u32 = 0o0000001;
const CS8: u32 = 0o0000060;
const ECHO: u32 = 0o0000010;
const ECHOE: u32 = 0o0000020;
const ECHOK: u32 = 0o0000040;
const ECHONL: u32 = 0o0000100;
const ISIG: u32 = 0o0000001;
const ICANON: u32 = 0o0000002;
const IEXTEN: u32 = 0o0100000;
const TCSAFLUSH: i32 = 2;

const VMIN: usize = 6;
const VTIME: usize = 5;

// ioctl TIOCGWINSZ
const TIOCGWINSZ: u64 = 0x5413;

#[repr(C)]
struct WinSize {
    ws_row: u16,
    ws_col: u16,
    ws_xpixel: u16,
    ws_ypixel: u16,
}

extern "C" {
    fn tcgetattr(fd: i32, termios: *mut Termios) -> i32;
    fn tcsetattr(fd: i32, optional_actions: i32, termios: *const Termios) -> i32;
    fn ioctl(fd: i32, request: u64, ...) -> i32;
    fn fcntl(fd: i32, cmd: i32, ...) -> i32;
}

const F_GETFL: i32 = 3;
const F_SETFL: i32 = 4;
const O_NONBLOCK: i32 = 0o0004000;

pub struct Terminal {
    orig_termios: Termios,
    pub rows: usize,
    pub cols: usize,
}

impl Terminal {
    pub fn new() -> io::Result<Terminal> {
        let mut orig: Termios = unsafe { mem::zeroed() };

        unsafe {
            if tcgetattr(0, &mut orig) < 0 {
                return Err(io::Error::last_os_error());
            }
        }

        let (rows, cols) = get_terminal_size()?;

        Ok(Terminal {
            orig_termios: orig,
            rows,
            cols,
        })
    }

    pub fn enable_raw_mode(&self) -> io::Result<()> {
        let mut raw: Termios = unsafe { mem::zeroed() };

        // Copy orig
        unsafe {
            tcgetattr(0, &mut raw);
        }

        raw.c_lflag &= !(ECHO | ICANON | ISIG | IEXTEN);
        raw.c_iflag &= !(IXON | ICRNL | BRKINT | INPCK | ISTRIP);
        raw.c_oflag &= !OPOST;
        raw.c_cflag |= CS8;
        raw.c_cc[VMIN] = 1;
        raw.c_cc[VTIME] = 0;

        unsafe {
            if tcsetattr(0, TCSAFLUSH, &raw) < 0 {
                return Err(io::Error::last_os_error());
            }
        }

        Ok(())
    }

    pub fn disable_raw_mode(&self) {
        unsafe {
            tcsetattr(0, TCSAFLUSH, &self.orig_termios);
        }
    }

    pub fn update_size(&mut self) -> io::Result<()> {
        let (rows, cols) = get_terminal_size()?;
        self.rows = rows;
        self.cols = cols;
        Ok(())
    }
}

fn get_terminal_size() -> io::Result<(usize, usize)> {
    unsafe {
        let mut ws: WinSize = mem::zeroed();

        if ioctl(1, TIOCGWINSZ, &mut ws) != -1 && ws.ws_col != 0 {
            return Ok((ws.ws_row as usize, ws.ws_col as usize));
        }

        // Fallback: move to bottom-right and query cursor position
        let mut stdout = io::stdout();
        stdout.write_all(b"\x1b[999C\x1b[999B")?;
        stdout.flush()?;

        // Query cursor position
        stdout.write_all(b"\x1b[6n")?;
        stdout.flush()?;

        let mut response = Vec::new();
        let mut buf = [0u8; 1];

        // Read response
        for _ in 0..32 {
            use std::io::Read;
            if std::io::stdin().read(&mut buf).unwrap_or(0) == 0 { break; }
            response.push(buf[0]);
            if buf[0] == b'R' { break; }
        }

        // Parse \x1b[rows;colsR
        if let Ok(s) = std::str::from_utf8(&response) {
            if let Some(start) = s.find('[') {
                let rest = &s[start+1..];
                if let Some(semi) = rest.find(';') {
                    let rows: usize = rest[..semi].parse().unwrap_or(24);
                    let cols: usize = rest[semi+1..].trim_end_matches('R').parse().unwrap_or(80);
                    return Ok((rows, cols));
                }
            }
        }

        Ok((24, 80))
    }
}

pub fn set_nonblocking(fd: i32, nonblocking: bool) -> i32 {
    unsafe {
        let flags = fcntl(fd, F_GETFL, 0);
        let new_flags = if nonblocking {
            flags | O_NONBLOCK
        } else {
            flags & !O_NONBLOCK
        };
        fcntl(fd, F_SETFL, new_flags)
    }
}

impl Drop for Terminal {
    fn drop(&mut self) {
        self.disable_raw_mode();
    }
}
