                }
            }
            if let Ok(s) = std::str::from_utf8(&utf8_bytes) {
                if let Some(ch) = s.chars().next() {
                    return Ok(Key::Char(ch));
                }
            }
            return Ok(Key::Unknown);
        }
    }

    Ok(Key::Unknown)
}

fn read_nonblocking(buf: &mut [u8]) -> usize {
    set_nonblocking(0, true);
    let result = io::stdin().read(buf).unwrap_or(0);
    set_nonblocking(0, false);
    result
}
