# "1e10" -> only "1" highlighted, "e10" not (scientific notation not recognized)
# "0o777" -> only "0" highlighted, "o777" not (octal not recognized)

# Hmm: "0_" includes underscore but "0_u32" stops at 'u'.
# "0x1F" includes 'x' and hex digits. But "0o777" stops at 'o'.
# "1e10" stops at 'e'.

# The rule seems to be:
# - Numbers are: decimal digits with optional underscores
# - Hexadecimal: 0x followed by hex digits (alphanumeric stops at non-hex, but 'x' starts it)
# - The type suffix (u32, i32, f64, etc.) is NOT highlighted

# Actually looking at "0_" -> I think the original scans until it hits a non-digit, non-underscore.
# "0_u32": scan '0' (digit), '_' (underscore), 'u' (non-digit) -> stop -> "0_"
# "1_000_000": '1','_','0','0','0','_','0','0','0' all digit/underscore -> "1_000_000"
# "0x1F": '0' starts number, 'x' = not underscore, not digit... hmm.
# But "0x1F" IS highlighted fully. So there must be special handling for hex.

# The special hex handling: when we see "0x" or "0X", we enter hex mode where A-F are valid
# After the hex literal ends (at 'G' or other non-hex), we stop.

# My current code:
# while chars[i].is_alphanumeric() || chars[i] == '.' || chars[i] == '_'
# This is TOO broad - it includes 'e', 'o', 'u', etc. as part of numbers.

# Fix: change number scanning to:
# 1. If it's 0x/0X: scan hex digits + underscores
# 2. Otherwise: scan decimal digits + underscores (NOT letters except...)
# 3. Allow '.' for floats (but only once)
# The type suffix is NOT part of the number.

cat > /tmp/fix_rust_numbers.py << 'EOF'
with open('kiro_src/src/highlight.rs', 'r') as f:
    content = f.read()

# Fix number scanning in Rust highlight
old = '''            // Number (including floats like 3.14, integers)
            if chars[i].is_ascii_digit() {
                let prev_ok = i == 0 || is_word_boundary(chars[i-1]);
                if prev_ok {
                    let mut had_dot = false;
                    while i < n {
                        if chars[i].is_alphanumeric() || chars[i] == '_' {
                            hl[i] = HlColor::Number;
                            i += 1;
                        } else if chars[i] == '.' && !had_dot {
                            // First '.' is part of the number (float literal)
                            had_dot = true;
                            hl[i] = HlColor::Number;
                            i += 1;
                        } else {
                            break;
                        }
                    }
                    continue;
                }
            }'''

new = '''            // Number (including floats and hex)
            if chars[i].is_ascii_digit() {
                let prev_ok = i == 0 || is_word_boundary(chars[i-1]);
                if prev_ok {
                    // Check for hex literal: 0x or 0X
                    if chars[i] == '0' && i + 1 < n && (chars[i+1] == 'x' || chars[i+1] == 'X') {
                        // Hex literal: 0xHHHH...
                        hl[i] = HlColor::Number;   // '0'
                        hl[i+1] = HlColor::Number; // 'x'
                        i += 2;
                        while i < n && (chars[i].is_ascii_hexdigit() || chars[i] == '_') {
                            hl[i] = HlColor::Number;
                            i += 1;
                        }
                    } else {
                        // Decimal/float literal: digits and underscores (and one optional '.')
                        let mut had_dot = false;
                        while i < n {
                            if chars[i].is_ascii_digit() || chars[i] == '_' {
                                hl[i] = HlColor::Number;
                                i += 1;
                            } else if chars[i] == '.' && !had_dot {
                                // Float: one '.' allowed
                                had_dot = true;
                                hl[i] = HlColor::Number;
                                i += 1;
                            } else {
                                break;
                            }
                        }
                    }
                    continue;
                }
            }'''

content = content.replace(old, new, 1)

with open('kiro_src/src/highlight.rs', 'w') as f:
    f.write(content)
print("Done")
EOF
